import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

const clientDir = join(process.cwd(), "dist", "client");
const headersPath = join(clientDir, "_headers");

const ASSET_CACHE_RULES = `
# Long-lived cache for self-hosted portfolio media (generated by append-asset-headers)
/projects/*
  Cache-Control: public, max-age=31536000, immutable

/brand/*
  Cache-Control: public, max-age=31536000, immutable
`;

if (!existsSync(clientDir)) {
  throw new Error(`[append-asset-headers] Missing build output at ${clientDir}. Run pnpm build first.`);
}

if (!existsSync(headersPath)) {
  throw new Error(`[append-asset-headers] Missing ${headersPath}. Vinext should generate this during build.`);
}

const existing = readFileSync(headersPath, "utf8");
if (existing.includes("/projects/*")) {
  process.exit(0);
}

appendFileSync(headersPath, ASSET_CACHE_RULES);